import sys
from collections import defaultdict, deque

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges_T1 = [(int(data[i*2+1]), int(data[i*2+2])) for i in range(n-1)]
    edges_T2 = [(int(data[(n-1)*2 + i*2+1]), int(data[(n-1)*2 + i*2+2])) for i in range(n-1)]

    return n, edges_T1, edges_T2

def build_tree(edges, n):
    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)
    return tree

def bfs(tree, start):
    parent = {start: None}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)
    return parent

def find_path(parent, start, end):
    path = []
    while end is not None:
        path.append(end)
        end = parent[end]
    return path[::-1]

